output_schema:
{
  "node_text": "String (Consequence + next situation. Max 2 sentences)",
  "visual_context": "String (Updated visual state. Reuse style + character + anchor)",
  "is_ending": Boolean,
  "choices": [
    { "choice_text": "Positive action", "behavior_type": "Positive" },
    { "choice_text": "Negative action", "behavior_type": "Negative" }
  ]
}

examples:
Example 1 (Positive Choice):
Input: Choice="Share the toy", Anchor="Green dinosaur, blue cap"
{
  "node_text": "Great! Your friend smiles and plays with you. It is more fun together.",
  "visual_context": "Pixar style, green dinosaur with blue cap, friend beside it, both smiling, playing together, sunny room",
  "is_ending": false,
  "choices": [
    { "choice_text": "Build tower together", "behavior_type": "Positive" },
    { "choice_text": "Take toy back", "behavior_type": "Negative" }
  ]
}

Example 2 (Negative Choice):
Input: Choice="Say no", Anchor="Green dinosaur, blue cap"
{
  "node_text": "Your friend feels sad and leaves. Playing alone is not as fun.",
  "visual_context": "Pixar style, green dinosaur with blue cap, sitting alone, sad face, empty room, quiet lighting",
  "is_ending": false,
  "choices": [
    { "choice_text": "Call friend back", "behavior_type": "Positive" },
    { "choice_text": "Keep playing alone", "behavior_type": "Negative" }
  ]
}
